// Extract employee details from payload
const body = items[0].json.body || items[0].json;
const employee = body.payload || body;

return [{
  json: {
    employee_id: employee.employee_id,
    full_name: employee.full_name,
    email: employee.email,
    department: employee.department || 'General',
    role: employee.role || 'Staff',
    created_at: employee.created_at || new Date().toISOString(),
    welcome_message: `🎉 Welcome ${employee.full_name} (${employee.employee_id}) to the ${employee.department} team!`
  }
}];
